interface BeautimaxIconProps {
    index: number
    className?: string
    style?: CSSProperties
}

export default function BeautimaxIcon({ index, className = "", style }: BeautimaxIconProps) {
    const encodedMarkup = framerIconMarkup[index]
    if (!encodedMarkup) return null

    return (
        <span
            className={`line-icon framer-svg-icon ${className}`.trim()}
            style={style}
            aria-hidden="true"
            dangerouslySetInnerHTML={{ __html: decodeURIComponent(encodedMarkup) }}
        />
    )
}
